import UIKit

class ContainerVC: UIViewController {
    @MainActor
    func embed(child: UIViewController) {
        addChild(child)
        view.addSubview(child.view)
        child.didMove(toParent: self)
    }
}

let root = ContainerVC()
let child = UIViewController()
root.embed(child: child)
print("Embedded children: \(root.children.count)")

import UIKit

@MainActor
func centerOf(view: UIView) -> CGPoint {
    return CGPoint(x: view.bounds.midX, y: view.bounds.midY)
}

let sampleView = UIView(frame: CGRect(x: 50, y: 50, width: 200, height: 100))
let centerPoint = centerOf(view: sampleView)
print("Center: \(centerPoint.x), \(centerPoint.y)")

import UIKit

struct SubviewManager {
    var subviewCount: Int = 0

    @MainActor
    mutating func addViews(to parent: UIView, count: Int) {
        for _ in 0..<count {
            let child = UIView()
            parent.addSubview(child)
        }
        subviewCount = parent.subviews.count
    }
}

let mainView = UIView()
var manager = SubviewManager()
manager.addViews(to: mainView, count: 3)
print("Count: \(manager.subviewCount)")
